import{s as r}from"./request-BwGmfNo-.js";const p={queryPpbom(e){return r.get("/wms-picking/ppbom/query",{params:{productionNo:e}})},push(e){return r.post("/wms-picking/push",e)},save(e){return r.post("/wms-picking/save",e)},send(e){return r.post(`/wms-picking/${e}/send`)},page(e=1,s=20,i){return r.get("/wms-picking/page",{params:{pageNum:e,pageSize:s,...i}})},entries(e){return r.get(`/wms-picking/${e}/entries`)},clearMaterial(e,s){return r.delete(`/wms-picking/${e}/material/${s}`)},getMaterialSummary(e,s){return r.get(`/wms-picking/${e}/material/${s}/summary`)}};export{p as w};
